    ("spinne", "Spinnentier"),
    ("biene", "Insekt"),
]

def finde_antwort(frage, beispiele):
    for eingabe, antwort in beispiele:
        if eingabe == frage:
            return antwort
    return "unbekannt"

print(finde_antwort("katze", beispiele))
